<script setup>
import{ref,computed,onMounted}from'vue';import{useRoute}from'vue-router';import{api}from'../services/api.js';import UiState from'../components/UiState.vue'
const route=useRoute(),today=new Date().toISOString().slice(0,10),from=ref(String(route.query.from||`${new Date().getFullYear()-6}-01-01`)),to=ref(String(route.query.to||today)),article=ref(String(route.query.article||'')),rows=ref([]),loading=ref(false),error=ref('')
const money=value=>new Intl.NumberFormat('ca-ES',{style:'currency',currency:'EUR'}).format(Number(value||0)),client=computed(()=>rows.value[0]||null),summary=computed(()=>rows.value.reduce((sum,row)=>{sum.lines++;sum.notes.add(row.delivery_note_number);sum.base+=Number(row.taxable_base||0);sum.vat+=Number(row.vat_amount||0);sum.total+=Number(row.total_amount||0);return sum},{lines:0,notes:new Set(),base:0,vat:0,total:0}))
const backQuery=computed(()=>({from:from.value,to:to.value,article:article.value}))
async function load(){loading.value=true;error.value='';try{rows.value=await api.get(`/sales/clients/${encodeURIComponent(route.params.clientCode)}?from=${from.value}&to=${to.value}&article=${encodeURIComponent(article.value)}`)}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load)
</script>
<template>
 <RouterLink :to="{path:'/sales-clients',query:backQuery}" class="button secondary back-button">← Tornar a vendes per client</RouterLink>
 <section class="card client-heading"><div><p class="eyebrow">Historial del client</p><h2>{{client?.client_name||'Client '+route.params.clientCode}}</h2><p class="muted">Codi {{route.params.clientCode}}</p></div></section>
 <form class="card filters sales-filters" @submit.prevent="load"><label>Des de<input v-model="from" type="date" required></label><label>Fins a<input v-model="to" type="date" required></label><label class="article-search">Article<input v-model="article" type="search" placeholder="Codi o nom de l’article"></label><button class="button primary">Consultar</button></form>
 <div class="summary-grid"><article class="card"><small>Albarans</small><strong>{{summary.notes.size}}</strong></article><article class="card"><small>Línies</small><strong>{{summary.lines}}</strong></article><article class="card"><small>Base</small><strong>{{money(summary.base)}}</strong></article><article class="card"><small>IVA</small><strong>{{money(summary.vat)}}</strong></article><article class="card"><small>Total</small><strong>{{money(summary.total)}}</strong></article></div>
 <UiState :loading="loading" :error="error" :empty="!rows.length" empty-text="No hi ha albarans amb aquests filtres."><div class="table-wrap"><table class="client-history-table"><thead><tr><th>Data</th><th>Albarà</th><th>Article</th><th>Concepte</th><th>Quantitat</th><th>Preu</th><th>Base</th><th>IVA</th><th>Total</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td data-label="Data">{{new Date(row.delivery_date).toLocaleDateString('ca-ES')}}</td><td data-label="Albarà"><strong>{{row.delivery_note_number}}</strong></td><td data-label="Article">{{row.product_code}}</td><td data-label="Concepte">{{row.concept}}<small v-if="row.waste_code">LER {{row.waste_code}}</small></td><td data-label="Quantitat">{{row.quantity}}</td><td data-label="Preu">{{money(row.unit_price)}}</td><td data-label="Base">{{money(row.taxable_base)}}</td><td data-label="IVA">{{money(row.vat_amount)}}</td><td data-label="Total"><strong>{{money(row.total_amount)}}</strong></td></tr></tbody></table></div></UiState>
</template>
